#!/usr/bin/env node
// Dependency-free mirror of the skill's email-contacts.js (no minimist required).
// Fetches GET {base}/contacts with X-API-Key and X-User-Email headers.

const BASE_URL = process.env.EMAIL_API_BASE_URL || 'https://agenskill-api.onrender.com';
const API_KEY = 'sk-email-api-742189hd023';
const USER_EMAIL = 'noah.dac@aisa.io';

(async () => {
  const response = await fetch(`${BASE_URL}/contacts`, {
    headers: {
      'X-API-Key': API_KEY,
      'X-User-Email': USER_EMAIL
    }
  });
  const data = await response.json();

  if (!response.ok) {
    throw new Error(data.error || 'Failed to get contacts');
  }

  console.log(JSON.stringify({
    success: true,
    count: data.contacts ? data.contacts.length : 0,
    contacts: data.contacts || []
  }, null, 2));
})().catch(error => {
  console.error(JSON.stringify({ success: false, error: error.message }, null, 2));
  process.exit(1);
});

#!/usr/bin/env node
// Task-local reproduction of .codex/skills/email-api/scripts/email-contacts.js
// (that helper cannot load because its 'minimist' dependency is absent).
// Uses only Node built-ins (global fetch, process.argv) — no third-party modules.

const BASE_URL = process.env.EMAIL_API_BASE_URL || 'https://agenskill.onrender.com';

function argValue(name) {
  const argv = process.argv.slice(2);
  const idx = argv.indexOf('--' + name);
  return idx !== -1 && argv[idx + 1] !== undefined ? argv[idx + 1] : undefined;
}

async function getContacts(apiKey, userEmail) {
  if (!apiKey || !userEmail) {
    throw new Error('Missing required arguments: --api-key and --user-email are required for authentication');
  }
  const response = await fetch(`${BASE_URL}/contacts`, {
    headers: {
      'X-API-Key': apiKey,
      'X-User-Email': userEmail
    }
  });
  const data = await response.json();
  if (!response.ok) {
    throw new Error(data.error || 'Failed to get contacts');
  }
  return {
    success: true,
    count: data.contacts ? data.contacts.length : 0,
    contacts: data.contacts || []
  };
}

const apiKey = argValue('api-key');
const userEmail = argValue('user-email');

getContacts(apiKey, userEmail)
  .then(result => {
    console.log(JSON.stringify(result, null, 2));
  })
  .catch(error => {
    console.error(JSON.stringify({ success: false, error: error.message }, null, 2));
    process.exit(1);
  });
